import { DEFAULT_CONSOLIDATION_KEYWORD_PROMPT } from './consolidationPromptDefaults.js';

/**
 * Runtime JSON loader for locales that don't support JSON import assertions
 */
export async function loadLocaleJson(lang) {
    const alias = {
        // Chinese (both already match ST base)
        'zh': 'zh-cn',
        'zh_cn': 'zh-cn',
        'zh_tw': 'zh-tw',
        'zh.tw': 'zh-tw',
        'zh-cn': 'zh-cn',
        'zh-tw': 'zh-tw',
        'zh-CN': 'zh-cn',
        'zh-TW': 'zh-tw',

        // Japanese -> ja-jp
        'ja': 'ja-jp',
        'ja_jp': 'ja-jp',
        'ja-JP': 'ja-jp',
        'ja-jp': 'ja-jp',

        // Russian -> ru-ru
        'ru': 'ru-ru',
        'ru_ru': 'ru-ru',
        'ru-RU': 'ru-ru',
        'ru-ru': 'ru-ru',

        // Spanish -> es-es
        'es': 'es-es',
        'es-es': 'es-es',

        // German -> de-de
        'de': 'de-de',
        'de_de': 'de-de',
        'de-DE': 'de-de',
        'de-de': 'de-de',

        // French -> fr-fr
        'fr': 'fr-fr',
        'fr_fr': 'fr-fr',
        'fr-FR': 'fr-fr',
        'fr-fr': 'fr-fr',

        // Korean -> ko-kr
        'ko': 'ko-kr',
        'ko_kr': 'ko-kr',
        'ko-KR': 'ko-kr',
        'ko-kr': 'ko-kr',

        // Malay -> ms-my
        'ms': 'ms-my',
        'ms_my': 'ms-my',
        'ms-MY': 'ms-my',
        'ms-my': 'ms-my',

        // Indonesian -> id-id
        'id': 'id-id',
        'id_id': 'id-id',
        'id-ID': 'id-id',
        'id-id': 'id-id',

        // Brazilian Portuguese -> pt-br
        'pt': 'pt-br',
        'pt_br': 'pt-br',
        'pt-BR': 'pt-br',
        'pt-br': 'pt-br',

        // English -> en (use built-in locales.js, no JSON file)
        'en': 'en',
        'en_us': 'en',
        'en-US': 'en',
        'en-us': 'en',
        'en_gb': 'en',
        'en-GB': 'en',
        'en-gb': 'en',
    };
    const normalized = alias[lang] || lang;

    const paths = {
        'zh-cn': './locales/zh-cn.json',
        'zh-tw': './locales/zh-tw.json',
        'ja-jp': './locales/ja-jp.json',
        'ru-ru': './locales/ru-ru.json',
        'es-es': './locales/es-es.json',
        'de-de': './locales/de-de.json',
        'fr-fr': './locales/fr-fr.json',
        'ko-kr': './locales/ko-kr.json',
        'ms-my': './locales/ms-my.json',
        'id-id': './locales/id-id.json',
        'pt-br': './locales/pt-br.json',
    };

    const rel = paths[normalized];
    if (!rel) return null;

    try {
        const res = await fetch(new URL(rel, import.meta.url));
        if (!res.ok) return null;
        return await res.json();
    } catch (e) {
        console.warn('STMemoryBooks: Failed to load locale JSON for', normalized, e);
        return null;
    }
}
