function formatLocalTopicalClipTimestamp(date = new Date()) {
    const pad = value => String(value).padStart(2, '0');
    return [
        date.getFullYear(),
        '-',
        pad(date.getMonth() + 1),
        '-',
        pad(date.getDate()),
        ' ',
        pad(date.getHours()),
        pad(date.getMinutes()),
    ].join('');
}

function makeDuplicateSafeTopicalFallbackHeadline(lorebookData, topic) {
    const base = `About ${validateClipHeadline(topic)} (Topical Clip ${formatLocalTopicalClipTimestamp()})`;
    let headline = base;
    let suffix = 2;
    while (getClipEntryByFinalTitle(lorebookData, makeClipEntryTitle(headline))) {
        headline = `${base} ${suffix}`;
        suffix += 1;
    }
    return headline;
}

function getTopicalDuplicateCreateMessage() {
    return tr('STMemoryBooks_TopicalClip_DuplicateCreateTitle', 'An entry with this title already exists. Choose update mode or use a different topic/title.');
}

function createTopicalClipRunMetadata({ topic, keywords, lorebookName, sourceSnapshot, messageSource = null }) {
    return {
        version: 2,
        topic,
        keywords,
        source_memory_book: lorebookName,
        last_successful_run_at: new Date().toISOString(),
        last_source_snapshot: sourceSnapshot,
        last_message_source: messageSource,
    };
}

async function saveTopicalClipDraft(context, draft, options = {}) {
    const {
        lorebookName,
        mode,
        topic,
        keywords,
        targetUid,
        targetContentHash,
        sourceSnapshot,
        messageSource,
    } = context || {};
    const contentDraft = String(draft || '').trim();
    if (!contentDraft) {
        throw new Error(tr('STMemoryBooks_TopicalClip_EmptyDraft', 'Generated draft is empty.'));
    }
    const keywordsArray = Array.isArray(keywords) ? keywords : [];

    let result = null;
    const entrySettings = context.entrySettings?.enabled ? context.entrySettings : null;
    await withStmbWriteLane({ type: 'lorebook', name: lorebookName }, async () => {
        const freshLorebook = await loadWorldInfo(lorebookName);
        if (!freshLorebook?.entries) {
            throw new Error(tr('STMemoryBooks_Error_FailedToLoadLorebook', 'Failed to load lorebook'));
        }
        if (context.messageSelection && !validateChatSelection(
            context.messageSelection, chat, getStmbChatKey(getCurrentStmbChatRef()))) {
            throw new Error(tr('STMemoryBooks_Extract_Changed', 'The chat or selected messages changed. Select them again.'));
        }

        if (mode === 'update' && !options.forceCreateNew) {
            const target = findEntryByStableId(freshLorebook, targetUid);
            if (!target) {
                throw new Error(tr('STMemoryBooks_TopicalClip_NoTargetEntry', 'Choose an entry to update.'));
            }
            const currentHash = stableHashString(String(target.content || ''));
            if (targetContentHash && currentHash !== targetContentHash) {
                const staleError = new Error(tr('STMemoryBooks_TopicalClip_TargetChanged', 'The selected Clip changed after draft generation.'));
                staleError.code = 'TOPICAL_CLIP_TARGET_CHANGED';
                throw staleError;
            }
            if (!!target.disable !== !!context.targetDisabled) {
                throw new Error(tr('STMemoryBooks_TopicalClip_TargetChanged', 'The selected Clip changed after draft generation.'));
            }

            const headline = getClipHeadlineFromTitle(target.comment || makeTopicalClipHeadline(topic));
            const format = context.format || getClipFormat(getClipFormatKind(target));
            target.content = createTopicalClipEntryContent(headline, contentDraft, format);
            setClipFormat(target, format, headline);
            target.key = keywordsArray;
            target.keysecondary = Array.isArray(target.keysecondary) ? target.keysecondary : [];
            target.constant = false;
            target.vectorized = true;
            target.selective = true;
            target.disable = false;
            applyClipInsertion(target, entrySettings);
            setTopicalClipMetadata(target, createTopicalClipRunMetadata({
                topic,
                keywords: keywordsArray,
                lorebookName,
                sourceSnapshot,
                messageSource,
            }));
            await saveLorebook(lorebookName, freshLorebook);
            result = { mode: 'update', lorebookData: freshLorebook };
            return;
        }

        const headline = options.forceCreateNew
            ? makeDuplicateSafeTopicalFallbackHeadline(freshLorebook, topic)
            : makeTopicalClipHeadline(topic);
        const title = makeClipEntryTitle(headline);
        if (getClipEntryByFinalTitle(freshLorebook, title)) {
            throw new Error(getTopicalDuplicateCreateMessage());
        }
        const entry = createWorldInfoEntry(lorebookName, freshLorebook);
        if (!entry) {
            throw new Error(tr('STMemoryBooks_Clip_ErrorCreateEntryFailed', 'Failed to create clip entry.'));
        }
        entry.comment = title;
        const format = options.forceCreateNew ? getClipFormat('topical') : context.format || getClipFormat('topical');
        entry.content = createTopicalClipEntryContent(headline, contentDraft, format);
        setClipFormat(entry, format, headline);
        entry.key = keywordsArray;
        entry.keysecondary = Array.isArray(entry.keysecondary) ? entry.keysecondary : [];
        entry.constant = false;
        entry.vectorized = true;
        entry.selective = true;
        entry.disable = false;
        entry.position = typeof entry.position === 'number' ? entry.position : 0;
        entry.order = typeof entry.order === 'number' ? entry.order : 100;
        applyClipInsertion(entry, entrySettings);
        setTopicalClipMetadata(entry, createTopicalClipRunMetadata({
            topic,
            keywords: keywordsArray,
            lorebookName,
            sourceSnapshot,
            messageSource,
        }));
        await saveLorebook(lorebookName, freshLorebook);
        result = { mode: 'create', lorebookData: freshLorebook };
    });
    return result;
}

export async function applyClipReviewSuggestion(lorebookName, candidate, options = {}) {
    let applied = false;
    await withStmbWriteLane({ type: 'lorebook', name: lorebookName }, async () => {
        const lorebookData = await loadWorldInfo(lorebookName);
        const entry = findEntryByStableId(lorebookData, candidate?.uid);
        if (!entry) throw new Error(tr('STMemoryBooks_ClipReview_TargetMissing', 'The suggested Clip no longer exists.'));
        if (entry.disable) throw new Error(tr('STMemoryBooks_ClipReview_TargetDisabled', 'This Clip is disabled. Run Memory Assistance again after enabling it.'));
        if (!isClipEntryTitle(entry.comment || '')) {
            throw new Error(tr('STMemoryBooks_ClipReview_TargetNotClip', 'The suggestion target is no longer an STMB Clip.'));
        }
        const actualType = getTopicalClipMetadata(entry) ? 'topical' : 'ordinary';
        if (candidate?.type !== actualType) {
            throw new Error(tr('STMemoryBooks_ClipReview_TargetTypeChanged', 'The Clip type changed after this review. Run Memory Assistance again.'));
        }
        if (candidate?.contentHash && stableHashString(entry.content || '') !== candidate.contentHash) {
            const error = new Error(tr('STMemoryBooks_ClipReview_TargetChanged', 'The Clip changed after this review. Run Memory Assistance again before applying the suggestion.'));
            error.code = 'CLIP_REVIEW_TARGET_CHANGED';
            throw error;
        }

        if (candidate.type === 'ordinary') {
            let content = String(entry.content || '');
            const headline = getClipHeadlineFromTitle(entry.comment || '');
            for (const addition of candidate.additions || []) {
                if (hasDuplicateBullet(content, addition.text)) continue;
                content = buildUpdatedExistingContent({ ...entry, content }, addition.text, headline);
            }
            if (content === entry.content) return;
            if (!options.skipLongEntryWarning && !await showLongEntryWarning(lorebookName, lorebookData, entry, content)) return;
            entry.content = content;
        } else {
            const headline = getClipHeadlineFromTitle(entry.comment || '');
            const format = getClipFormat(getClipFormatKind(entry));
            entry.content = createTopicalClipEntryContent(headline, candidate.proposedContent, format);
            setClipFormat(entry, format, headline);
            const prior = getTopicalClipMetadata(entry) || {};
            setTopicalClipMetadata(entry, {
                ...prior,
                version: Math.max(2, Number(prior.version || 0)),
                last_successful_run_at: new Date().toISOString(),
                last_message_source: candidate.messageSource || prior.last_message_source || null,
            });
        }
        await saveLorebook(lorebookName, lorebookData);
        applied = true;
    });
    return applied;
}

